window.BIZ_PAPERS = (window.BIZ_PAPERS || []).concat([{"id": "ENGI2-SAM", "unit": 2, "key": "SAM", "series": "Sample assessment (AAQ)", "date": "Pearson sample assessment material", "title": "Pearson sample paper", "source": "pearson", "kind": "exam", "code": "Sample", "spec": "new", "total": 70, "minutes": 120, "items": [{"q": 1, "sub": "", "marks": 1, "section": "A", "ctx": [], "text": "Which one of these engineering sectors is involved with the design and development\nof buildings?\nA Agricultural\nB Civil\nC Chemical\nD Rail", "ms": {"body": "Award one mark for the correct response:\n• B Civil", "levels": null}}, {"q": 2, "sub": "", "marks": 1, "section": "A", "ctx": [], "text": "Which one of these engineering functional areas ensures that manufactured\nproducts comply with required standards?\nA Sales and marketing\nB Energy management\nC Quality management\nD Information management", "ms": {"body": "Award one mark for the correct response:\n• C Quality management", "levels": null}}, {"q": 3, "sub": "", "marks": 1, "section": "A", "ctx": [], "text": "Health and safety management is a functional area of an engineering organisation.\nState one specific activity carried out by the health and safety management\nfunctional area.", "ms": {"body": "Award one mark for a correctly given activity\nfrom:\n• Risk assessment (1)\n• Monitoring health and safety incidents\nand accidents (1)\n• Statutory reporting of incidents and\naccidents (1)\n• Emergency planning (1)\n• Health and safety training/education (1)\nAccept any other appropriate response.", "levels": null}}, {"q": 4, "sub": "", "marks": 1, "section": "A", "ctx": [], "text": "State the functional area of an engineering organisation responsible for creating\nengineering drawings.", "ms": {"body": "Award one mark for a correctly given functional\narea from:\n• Design of products and services (1)\n• Drawing office (1)\n• Design office (1)\nAlso accept:\n• Technical drawing office (1)\nAccept any other appropriate response.", "levels": null}}, {"q": 5, "sub": "", "marks": 2, "section": "A", "ctx": [], "text": "Explain one benefit of using sensors connected to the Internet of Things (IoT).", "ms": {"body": "Award one mark for a correct benefit (1) and\none mark for a justification for that benefit (1),\nup to a maximum of two marks.\nMarking points may be reversed/given in any\norder.\n• [Enables real time analysis and decision\nmaking / enables predictive maintenance]\n(1) because sensors are connected to the\nIoT enables real time monitoring of\nparameters (like temperature, pressure,\nvibration) (1).\n• Enables efficiency improvements (1)\nbecause it can optimise processes (by\nanalysing/processing real time sensor\ndata) (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 6, "sub": "", "marks": 2, "section": "A", "ctx": [], "text": "Explain one benefit of using cloud computing.", "ms": {"body": "Award one mark for a correct benefit (1) and\none mark for a justification for that benefit (1),\nup to a maximum of two marks.\nMarking points may be reversed/given in any\norder.\n• Allows businesses to quickly expand their\nstorage capacity without the need for\nphysical hardware upgrades (1) because\ncloud computing allows for easy and\nrapid storage capacity expansion (1).\n• Makes it easier for employees to [work\nremotely / collaborate on projects] (1)\nbecause cloud data can be accessed from\nanywhere with an internet connection\n(1).\n• Reduces overall running costs (1)\nbecause cloud computing eliminates the\nneed to purchase [hardware / software]\n(1).\n• Provides quick recovery after a major\nincident such as a fire (1) because cloud\ncomputing keeps data backed up\nremotely (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 7, "sub": "", "marks": 2, "section": "A", "ctx": [], "text": "Explain one benefit of using cooperative robots (cobots).", "ms": {"body": "Award one mark for a correct benefit (1) and\none mark for a justification for that benefit (1),\nup to a maximum of two marks.\nMarking points may be reversed/given in any\norder.\n• Cobots provide enhanced safety (1)\nbecause they are designed to work in\nclose proximity to human workers (1).\n• Cobots provide increased productivity (1)\nbecause they assist human workers with\n[repetitive / physically demanding] tasks\n(1).\n• Cobots are [versatile / flexible /\nadaptable] (1) because they can be\nquickly and easily [installed / trained /\nre-programmed] (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 8, "sub": "", "marks": 3, "section": "A", "ctx": [], "text": "Research and development is a functional area of an engineering organisation.\nExplain one benefit of using 3D printing in research and development.", "ms": {"body": "Award one mark for each appropriate benefit\n(1), one further mark for a justification for that\nbenefit (1), and one mark for expansion of the\njustification (1) up to a maximum of three\nmarks.\n• 3D printing reduces the time to market\n(1) because it enables rapid prototyping\n(1) which [reduces time required to test\na new iteration / speeds up the whole\ndesign process reducing time to market]\n(1).\n• 3D printing inspires innovation (1)\nbecause it [allows greater creativity and\ndesign freedom / is not constrained by\nconventional manufactured processes]\n(1) which enables [novel /\nunconventional / geometrically complex]\ndesign solutions (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 9, "sub": "", "marks": 3, "section": "A", "ctx": [], "text": "Quality management is a functional area of an engineering organisation.\nExplain one benefit of using artificial intelligence (AI) in quality management.", "ms": {"body": "Award one mark for each appropriate benefit\n(1), one further mark for a justification for that\nbenefit (1), and one mark for expansion of the\njustification (1) up to a maximum of three\nmarks.\n• AI enables the identification of quality\nissues in real time (1) because it enables\nvision recognition systems to visually\ninspect products (1) which enables\n[immediate interventions / reliable\nidentification of issues in quality] (1).\n• AI can [speed up the resolution of quality\nissues / reduce the number of quality\nissues] (1) because it can [synthesise /\nanalyse] complex data (1) which enables\nit to trace root causes of issues (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 10, "sub": "", "marks": 9, "section": "A", "ctx": [], "text": "Design of engineering products and services is a functional area of an engineering\norganisation.\nDiscuss the impact of using Virtual Reality (VR) in the design of engineering products\nand services.", "ms": {"body": "Students might refer to some/all of the following in their\nresponses, but students should be rewarded for other pertinent\ncontextualised answers.\nThe design of engineering product and services involves the\nfollowing activities:\n• using a design brief or specification to develop a\nproduct/service suitable for manufacture/delivery\n• creation of engineering drawings\n• component specifications\n• manufacturing instructions\n• process instructions\n• flow charts and design documentation.\nThe principal applications of VR in this context relate to the\ndevelopment of a product/service suitable for\nmanufacture/delivery:\n• VR allows designers to create and visualise design\nconcepts in a virtual environment\n• Designers can create virtual 3D models and prototypes\nand then experience immersive virtual representations\nof them without having to build a physical model. They\ncan interact with the design and experience its form,\n26\nfunction and usability informing subsequent redesign\nand development\n• VR allows collaboration where designers, engineers, and\nclients are able to work together remotely. Participants\ncan view and interact with designs together in real time\nto provide feedback and suggestions. This reduces the\nneed for physical prototypes and the time and expense\nof travelling to meetings which is a much more cost\neffective and efficient way of working\n• VR is able to simulate the use of a product or service in\nvarious contexts or scenarios. This allows clients to\nvisualise and experience the product/service before it is\nphysically available. By capturing user reactions,\npreferences and feedback through VR experiences,\ndesigners can make improvements, validate design\ndecisions, and ensure they fully meet customer\nexpectations\n• VR does have its drawbacks. These include the high cost\nof VR hardware and the development costs of creating\nvirtual environments. Some users experience physical\ndiscomfort, motion sickness or eye strain when using\nVR. Additionally, use of VR can lead to a loss in\nawareness of your physical surroundings which can\nincrease the likelihood of trips or falls.\nMark scheme (award up to 9 marks) refer to the guidance earlier in this\ndocument for how to apply levels-based mark schemes\nLevel\nDescriptors\nThe second trait (application) carries twice as much weighting as trait 1 (analysis).\n0\nNo rewardable material\n1\n1 - 3\n• Demonstrates a basic analysis of the situation by\nsuperficially breaking down the different aspects into\ntheir component parts.\n• Demonstrates basic application of knowledge and\nunderstanding that is partially relevant to the context\nof the question and may consider only one side of the\ncontext.\n2\n4 - 6\n• Demonstrates a good analysis of the situation by\nbreaking down the different aspects into their\ncomponent parts.\n• Demonstrates good application of knowledge and\nunderstanding that is relevant to the context of the\nquestion and considers both sides of the context.\n7 - 9\n• Demonstrates a thorough analysis of the situation by\ncomprehensively breaking down the different aspects\ninto their component parts.\n• Demonstrates comprehensive application of knowledge\nand understanding that is consistently relevant to the\ncontext of the question and considers both sides of the\ncontext in a balanced way.", "levels": null}}, {"q": 11, "sub": "", "marks": 1, "section": "B", "ctx": [], "text": "Which one of these is a thermoplastic elastomer?\nA Styrenic block copolymer (SBC)\nB Nitrile rubber\nC Polychloroprene\nD Polylactic acid", "ms": {"body": "Award one mark for the correct response:\n• A Styrenic block copolymer (SBC)", "levels": null}}, {"q": 12, "sub": "", "marks": 1, "section": "B", "ctx": [], "text": "Which one of these is a high carbon steel?\nA Fe with 0.20% C\nB Fe with 0.50% C\nC Fe with 1.20% C\nD Fe with 3.40% C", "ms": {"body": "Award one mark for the correct response:\n• C Fe with 1.20%C", "levels": null}}, {"q": 13, "sub": "", "marks": 2, "section": "B", "ctx": [], "text": "Explain one benefit of blanking out sheet metal components on a press.", "ms": {"body": "Award one mark for a correct benefit (1) and\none mark for a justification for that benefit (1),\nup to a maximum of two marks.\n• blanking out produces an entire\ncomponent in one operation (1) because\nit uses a dedicated hard tool (1).\n• blanking out provides high production\nrates (1) because it blanks out an entire\ncomponent in one operation (1).\n• blanking out provides good [dimensional\ncontrol / repeatability / component\nflatness] (1) because it uses a dedicated\nhard tool (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 14, "sub": "", "marks": 1, "section": "B", "ctx": [], "text": "Define the term electrical resistivity.", "ms": {"body": "Award one mark for a correct definition from:\n• Electrical resistivity quantifies how\nstrongly a given material opposes the\nflow of electric current (1).\n• The resistance of a conducting material\nwith a unit length and cross-sectional\narea (1).\n• The ratio between the voltage applied to\ncurrent flowing through it.\nAccept any other appropriate response.", "levels": null}}, {"q": 15, "sub": "", "marks": 1, "section": "B", "ctx": [], "text": "State the material group to which neoprene belongs.", "ms": {"body": "Award one mark for a correctly given material\ngroup from:\n• Thermoset elastomers (1)\nAlso accept:\n• Synthetic rubbers (1)\nAccept any other appropriate response.", "levels": null}}, {"q": 16, "sub": "", "marks": 2, "section": "B", "ctx": [], "text": "Explain one benefit of cutting holes using electro discharge machining (EDM).", "ms": {"body": "Award one mark for a correct benefit (1) and\none mark for a justification for that benefit (1),\nup to a maximum of two marks.\nMarking points may be reversed/given in any\norder.\n• EDM cut any metal/hard metals (1)\nbecause it is a non-mechanical process\nusing spark erosion to remove metal (1).\n• EDM can cut holes of any shape (1) the\nshape of the hole is dictated by the\nshape of the electrode (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 17, "sub": "", "marks": 2, "section": "B", "ctx": [], "text": "Explain one benefit of cutting engineering materials using a water jet.", "ms": {"body": "Award one mark for a correct benefit (1) and one\nmark for a justification for that benefit (1), up to a\nmaximum of two marks.\nMarking points may be reversed/given in any\norder.\n• Water jet cutting does not cause a heat\naffected zone/thermal stress when cutting\n(1) because it is a cool process (1).\n• Water jet cutting is very versatile (1)\nbecause it can cut a wide range of materials\nmetals/ceramics/composites/polymers (1).\n• Water jet cutting can cut complex shapes to\ntight tolerances (1) because the process\nprovides high precision and accuracy (1).\n• Water jet cutting is environmentally friendly\n(1) because it doesn’t involve harmful\nchemicals/fumes/emissions (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 18, "sub": "", "marks": 6, "section": "B", "ctx": [], "text": "Explain three steps in the process of resin transfer moulding (RTM).", "ms": {"body": "Award one mark for a correct step in the\nprocess (1), one mark for a justification for that\nstep (1) up to a maximum of six marks.\nMarking points may be reversed/given in any\norder.\n• Material layered (1) because the correct\nthickness and orientation needs to be\nachieved (1).\n• Release compound is applied (to the internal\nsurface of the mould) (1) because there is a\nrisk that the injective resin could stick to the\nmould (1).\n• Material is positioned into the bottom half of\nthe mould cavity (in the correct orientation)\n(1) because there is a risk of misalignment\nof the fibres (1).\n• The top half of the mould is lowered into\nplace (1) because the mould needs to be\nclosed and sealed to form the mould cavity\n(1).\n• Low viscosity epoxy resin is pumped into the\nmould cavity (1) because it needs to flow\nthrough all of the fibre matting (1).\n• The resin impregnated component is left to\ncure (1) because it takes time to harden into\nthe finished component (1).\n• Once cured the mould is opened and the\nfinished component can be removed (1)\nbecause [the component needs to be\nfinished outside the mould / mould reused\nfor next component] (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 19, "sub": "", "marks": 2, "section": "B", "ctx": [], "text": "Explain one effect of the annealing heat treatment process.", "ms": {"body": "Award one mark for a correct effect (1) and one\nmark for a justification for that effect (1), up to a\nmaximum of two marks.\nMarking points may be reversed/given in any\norder.\n• Annealing reduces hardness/softens\nmetals (1) because it promotes the\nformation of large grains (1).\n• Annealing relieves internal stress (1)\nbecause it causes recrystallisation of the\ngrain structure (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 20, "sub": "", "marks": 3, "section": "B", "ctx": [], "text": "Explain one reason why urea formaldehyde (UF) is not suitable for use in a\nconventional thermoplastic injection moulding machine.", "ms": {"body": "Award one mark for each appropriate reason\n(1), one further mark for a justification for that\nreason (1), and one mark for expansion of the\njustification (1) up to a maximum of three\nmarks.\n●\nUF would [cause damage to a\nconventional thermoplastic injection\nmoulding machine / not reach the\nmould] (1) because UF would cure when\nheated in the barrel of the moulding\nmachine (1) as when it is heated\npermanent links form between the\npolymer chains and it hardens (1).\nAccept any other appropriate response.", "levels": null}}, {"q": 21, "sub": "", "marks": 12, "section": "B", "ctx": [], "text": "Metalwork vices are often seen in engineering workshops.\nThe main body of the vice is mass produced from cast iron.\nMain body of vice\nThere are two casting processes that could be used to manufacture the main body of\nthe vice:\n• sand casting\n• investment casting\nThe main body of the vice has the following characteristics:\n• surface finish\n• dimensional accuracy\n• component size\nEvaluate the suitability of these two processes to manufacture the main body of\nthe vice.", "ms": {"body": "Students might refer to some / all of the following in their\nresponses, but students should be rewarded for other pertinent\ncontextualised answers.\nAnalysis\nThe body of a vice has the following important characteristics:\n• Surface finish – there is no functional reason to having a\nsmooth surface finish. A textured finish could be\nadvantageous as it is non-slip and will also help retain a\npainted finish for longer.\n• Dimensional accuracy – the vice body has only one feature\nthat mates with other components and needs to be\ndimensionally accurate. This feature could be machined in\npost processing.\n• Component size – the component itself is large.\nCast iron has the following properties:\n• High melting point\n• High [density / weight].\nOther relevant factors:\n• Mass production – process must be suitable for mass\nproduction with low unit costs.\nSand casting\n• produces a rough surface finish which is appropriate for the\nsurface of the vice body.\n• has [limited / low] dimensional accuracy which is\nappropriate for the vice body BUT mating surfaces would\nhave to be machined after moulding.\n• involves using a pattern of the component to create a\nmould using sand and a bonding agent and is suitable for\nmanufacturing large components.\n• is well suited for use with cast iron due to its ability to\nwithstand thermal shock and handle high melting point\nmaterials with high pouring temperatures.\n• sand moulds are robust and provide good support for heavy\ncomponents like the vice body.\n• is suited to mass production as it is a cost-effective process\nwith low unit costs. The single use moulds are inexpensive,\nquick to make and the moulding sand can be re-used.\nInvestment casting\n• produces a very smooth surface finish which is not a\nrequired characteristic of the vice body.\n• has excellent dimensional accuracy which is not a required\ncharacteristic of the vice body but could eliminate the need\nfor post process machining of mating surfaces.\n33\nLevel\nDescriptors\nThe second trait (application) carries twice as much weighting as trait 1 (analysis)\nand trait 3 (evaluation).\n0\nNo rewardable material\n1\n1 – 4\n• Demonstrates a basic analysis of the situation by\nsuperficially breaking down the different aspects into\ntheir component parts.\n• Demonstrates basic application of knowledge and\nunderstanding that is partially relevant to the context\nof the question and may consider only one side of the\ncontext\n• involves the manufacture of an individual wax model of the\nvice body, coating this in layers of refractory clay and\nmelting out the wax to make each casting [investment /\nmould]. This is a complex process best suited to small\ncomponents that can be mounted in trees allowing several\nto be cast at once. It is much less suitable for casting large\nsingle components.\n• ceramic [investments / moulds] can handle high melting\npoint materials like cast iron but are less able to withstand\nthermal shock and require pre-heating prior to use. This\nadds further cost and process complexity.\n• ceramic [investments / moulds] provide relatively poor\nsupport for heavy components like the vice body.\n• is not well suited to mass production as it has relatively\nhigh unit costs. The multistage method of manufacturing\nceramic [investments / moulds] is relatively expensive and\ntime consuming and although the wax can be reused the\nrefractory clay cannot.\nConclusion\nSand casting would be the most suitable manufacturing method\nfor the cast iron vice bodies because it:\n• provides sufficient levels of surface finish and dimensional\naccuracy\n• allows high pouring temperatures without the need for pre-\nheating to avoid thermal shock\n• is quicker, easier and less expensive to produce sand\nmoulds than investments\n• uses sand moulds that are more suitable for the\nmanufacture of large single components\n• is better able to support the weight of large components\nduring manufacture\n• is a simpler more cost-effective process better suited to\nmass production of large components\n• offsets the cost of post processing mating surfaces by being\nquicker and much less expensive overall.\nMark scheme (award up to 12 marks) refer to the marking guidance earlier in\nthis document for how to apply levels-based mark schemes\n34\n• Demonstrates basic evaluation which partially\nconsiders different factors/events and competing\npoints, leading to a conclusion which is superficial or\nunsupported.\n2\n5 – 8\n• Demonstrates a good analysis of the situation by\nbreaking down the different aspects into their\ncomponent parts.\n• Demonstrates good application of knowledge and\nunderstanding that is relevant to the context of the\nquestion and considers both sides of the context.\n• Demonstrates a good evaluation which considers\ndifferent factors/events and competing points, leading\nto a conclusion which is partially supported.\n9 – 12\n• Demonstrates a thorough analysis of the situation by\ncomprehensively breaking down the different aspects\ninto their component parts.\n• Demonstrates comprehensive application of\nknowledge and understanding that is consistently\nrelevant to the context of the question and considers\nboth sides of the context in a balanced way.\n• Demonstrates a thorough evaluation which\ncomprehensively considers different factors/events\nand competing points, leading to a conclusion which is\nwell supported.", "levels": null}}, {"q": 22, "sub": "", "marks": 12, "section": "B", "ctx": [], "text": "Safety glasses are used for eye protection in the workplace.\nLenses\nThere is a choice of two polymers for the lenses.\nThe properties of these polymers are summarised in the table:\nPolycarbonate\n(PC)\nPolyethylene\nterephthalate\n(PET)\nDensity (kg/m3)\n1200\n1100\nMelting point (°C)\nChemical resistance\nGood\nGood\nLight transmission (%)\nRockwell Hardness HRR\nImpact toughness (kJ/m2)\nDuctility (% elongation at break)\nTensile strength (MPa)\nModulus of elasticity (MPa)\n4000\n1570\nColour\nColourless\nColourless\nEvaluate the suitability of these two polymers in terms of:\n• light transmission\n• impact resistance\n• hardness (scratch resistance)\n• weight\n• chemical resistance", "ms": {"body": "Students might refer to some/all the following in their responses,\nbut students should be rewarded for other pertinent contextualised\nanswers.\nAnalysis\nThe lenses of the safety glasses have the following important\ncharacteristics:\n• light transmission – lenses must be colourless and have\nhigh light transmission to ensure clear vision when the user\nlooks through them\n• impact resistance –lenses must absorb impact energy and\nnot shatter to provide the required level of eye protection\n• hardness – lenses must be scratch resistant to prevent\nscratches building up over time on the surface of the lenses\nand obscuring vision\n• weight – lenses must be lightweight to ensure the comfort\nof the wearer (low weight is directly related to low material\ndensity)\n• chemical resistance – lenses must be resistant to solvents\nand other chemicals as any reaction would damage their\nsurface and obscure vision.\nPolycarbonate (PC) has:\n• high light transmission properties (90%) and is colourless\nwhich are both essential for clear vision when looking\nthrough the lenses\n• high impact toughness (65kJ/m2) which is essential for\nproviding good eye protection\n• high hardness (125HRR) for a polymer and so will provide\ngood scratch resistance\n• low density (1200kg/m3) meaning lenses would be\nlightweight ensuring the comfort of the wearer\n• has good chemical resistance and will not be damaged by\nsolvents and other chemicals.\nPolyethylene terephthalate (PET) has:\n• good light transmission properties (67%) and is colourless\nwhich are both essential for clear vision when looking\nthrough the lenses\n• low impact toughness (6kJ/m2) and so provides relatively\npoor eye protection\n• low hardness (45HRR) and so will provide relatively poor\nscratch resistance\n• low density (1100kg/m3) meaning lenses would be\nlightweight ensuring the comfort of the wearer\n• has good chemical resistance and will not be damaged by\nsolvents and other chemicals.\n36\nLevel\nDescriptors\nThe second trait (application) carries twice as much weighting as trait 1 (analysis)\nand trait 3 (evaluation).\n0\nNo rewardable material\n1\n1 – 4\n• Demonstrates a basic analysis of the situation by\nsuperficially breaking down the different aspects into\ntheir component parts.\n• Demonstrates basic application of knowledge and\nunderstanding that is partially relevant to the context\nof the question and may consider only one side of the\ncontext.\n• Demonstrates a basic evaluation which partially\nconsiders different factors/events and competing\npoints, leading to a conclusion which is superficial or\nunsupported.\n2\n5 – 8\n• Demonstrates a good analysis of the situation by\nbreaking down the different aspects into their\ncomponent parts.\n• Demonstrates good application of knowledge and\nunderstanding that is relevant to the context of the\nquestion and considers both sides of the context.\n• Demonstrates a good evaluation which considers\ndifferent factors/events and competing points, leading\nto a conclusion which is partially supported.\n9 – 12\n• Demonstrates a thorough analysis of the situation by\ncomprehensively breaking down the different aspects\ninto their component parts.\nConclusion\nPC is the most suitable of the two polymers for the lenses of safety\nglasses because:\n• PC and PET are both colourless, but PC has better light\ntransmission than PET and will provide clearer vision\n• PC has much higher impact toughness than PET and will\nprovide better eye protection\n• PC has much higher hardness than PET and will provide\nbetter scratch resistance\n• PC and PET have similar density, and both will provide\nlightweight lenses with good levels of comfort for the\nwearer. This was not a deciding factor between the\nmaterials\n• PC and PET have good chemical resistance, and both will\nnot be damaged by solvents or chemicals. This was not a\ndeciding factor between the materials.\nMark scheme (award up to 12 marks) refer to the marking guidance earlier in\nthis document for how to apply levels-based mark schemes\n37\n• Demonstrates comprehensive application of\nknowledge and understanding that is consistently\nrelevant to the context of the question and considers\nboth sides of the context in a balanced way.\n• Demonstrates a thorough evaluation which\ncomprehensively considers different factors/events\nand competing points, leading to a conclusion which is\nwell supported.\n38\nFebruary 2026\nFor information about Pearson Qualifications, including Pearson Edexcel\nand BTEC qualifications visit qualifications.pearson.com\nEdexcel and BTEC are registered trademarks of Pearson Education Limited\nPearson Education Limited. Registered in England and Wales No. 872828\nRegistered Office: 80 Strand, London WC2R 0RL.\nVAT Reg No GB 278 537121", "levels": null}}], "badge": "Pearson · current spec", "badgeTone": "new", "notice": "Pearson’s sample assessment for the current AAQ specification: the closest match to the real exam. Figures, tables and information booklets are described in words."}]);
